export const SN_W = 1000;
export const SN_H = 736;
export const SN_VIEWBOX = `0 0 ${SN_W} ${SN_H}`;

// Projection calée sur l'emprise du Sénégal (12°18'N–16°41'N, 11°21'W–17°32'W) et le cadre
// du SVG : 13 capitales régionales sur 14 tombent dans leur région (Saint-Louis, sur l'île,
// est en bordure de côte).
export function geoToSvg(lng: number, lat: number): { x: number; y: number } {
  return {
    x: 147.016 * lng + 2623.13,
    y: -152.635 * lat + 2579.81,
  };
}

